    ldp   x5, x6, [x2, #16]
    ldp   x7, x8, [x2, #32]
    ldp   x9, x10, [x2, #48]
    ldp   x21, x22, [x2, #64]
    adds  x3, x3, x21
    adcs  x4, x4, x22
    ldp   x21, x22, [x2, #80]
    adcs  x5, x5, x21
    adcs  x6, x6, x22
    ldp   x21, x22, [x2, #96]
    adcs  x7, x7, x21
    adcs  x8, x8, x22
    ldp   x21, x22, [x2, #112]
