    movk  x22, #0x43ff, lsl #16
    movk  x22, #0x0009, lsl #32      // p[7]
    subs  x19, x19, x21
    sbcs  x20, x20, x21
    sbcs  x11, x11, x21
    sbcs  x12, x12, x21
    sbcs  x13, x13, x21
    sbcs  x14, x14, x21
    sbcs  x15, x15, x21
    sbcs  x16, x16, x22
