    sbcs  x4, x4, x19
    sbcs  x5, x5, x20
    sbcs  x6, x6, x11
    sbcs  x7, x7, x12
    sbcs  x8, x8, x13
    sbcs  x9, x9, x14
    sbcs  x10, x10, x15
