    // c1 = (P2 - P1) - P0
    ldp   x3, x4, [sp]
    ldp   x5, x6, [sp, #16]
    ldp   x7, x8, [sp, #32]
    ldp   x9, x10, [sp, #48]
    movz  x22, #0xffff
    movk  x22, #0x43ff, lsl #16
    movk  x22, #0x0009, lsl #32      // p[7]
    subs  x3, x3, x17
    sbcs  x4, x4, x19
    sbcs  x5, x5, x20
    sbcs  x6, x6, x11
    sbcs  x7, x7, x12
    sbcs  x8, x8, x13
    sbcs  x9, x9, x14
    sbcs  x10, x10, x15
    sbc   x21, xzr, xzr              // mask = -borrow
    and   x22, x22, x21
    adds  x3, x3, x21
    adcs  x4, x4, x21
    adcs  x5, x5, x21
    adcs  x6, x6, x21
    adcs  x7, x7, x21
    adcs  x8, x8, x21
    adcs  x9, x9, x21
    adc   x10, x10, x22
    ldp   x17, x19, [sp, #64]
    ldp   x20, x11, [sp, #80]
    ldp   x12, x13, [sp, #96]
    ldp   x14, x15, [sp, #112]
    movz  x22, #0xffff
    movk  x22, #0x43ff, lsl #16
    movk  x22, #0x0009, lsl #32      // p[7]
    subs  x3, x3, x17
    sbcs  x4, x4, x19
    sbcs  x5, x5, x20
    sbcs  x6, x6, x11
    sbcs  x7, x7, x12
    sbcs  x8, x8, x13
    sbcs  x9, x9, x14
    sbcs  x10, x10, x15
    sbc   x21, xzr, xzr              // mask = -borrow
    and   x22, x22, x21
    adds  x3, x3, x21
    adcs  x4, x4, x21
    adcs  x5, x5, x21
    adcs  x6, x6, x21
    adcs  x7, x7, x21
    adcs  x8, x8, x21
    adcs  x9, x9, x21
    adc   x10, x10, x22
    stp   x3, x4, [x0, #64]
    stp   x5, x6, [x0, #80]
    stp   x7, x8, [x0, #96]
    stp   x9, x10, [x0, #112]
    ldp   x21, x22, [sp, #144]
    ldp   x19, x20, [sp, #128]
    add   sp, sp, #160
    ret

//***********************************************************************
//  Squaring in GF(p^2)
//  Operation: c0 = (a0+a1) x (a0-a1) ; c1 = 2 a0 x a1
//    with a0+a1, a0-a1+p and 2*a0 kept unreduced (< 2p), so both
//    Montgomery products are < 2p before their final reduction.
//  Inputs: a = [a0, a1] stored in [x1]
//  Output: c = [c0, c1] stored in [x0]  (c may alias a)
//  Register allocation: multiplicand (d = a0-a1+p, then a1) = x3..x10;
//                       acc z0..z8 = x11..x17,x19,x20,
//                       scalar bi = x21, MULADD temp x22;
//                       scalars streamed from [sp].
//  Stack: [sp+0 .. 64) holds s = a0+a1;
//         [sp+64 .. 128) holds t = 2*a0.
//***********************************************************************
.global CDECL(fp2_sqr)
.p2align 6
CDECL(fp2_sqr):
    sub   sp, sp, #160               // 128 for s + t + 32 for callee saves
    stp   x19, x20, [sp, #128]
    stp   x21, x22, [sp, #144]

    // t = 2*a0 (unreduced) -> [sp+64] ; a0 stays in x3..x10
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]
    adds  x11, x3, x3
    adcs  x12, x4, x4
    adcs  x13, x5, x5
    adcs  x14, x6, x6
    adcs  x15, x7, x7
    adcs  x16, x8, x8
    adcs  x17, x9, x9
    adc   x19, x10, x10
    stp   x11, x12, [sp, #64]
    stp   x13, x14, [sp, #80]
    stp   x15, x16, [sp, #96]
    stp   x17, x19, [sp, #112]
    // s = a0 + a1 (unreduced) -> [sp]
    ldp   x11, x12, [x1, #64]
    ldp   x13, x14, [x1, #80]
    ldp   x15, x16, [x1, #96]
    ldp   x17, x19, [x1, #112]
    adds  x11, x11, x3
    adcs  x12, x12, x4
    adcs  x13, x13, x5
    adcs  x14, x14, x6
    adcs  x15, x15, x7
    adcs  x16, x16, x8
    adcs  x17, x17, x9
    adc   x19, x19, x10
    stp   x11, x12, [sp]
    stp   x13, x14, [sp, #16]
    stp   x15, x16, [sp, #32]
    stp   x17, x19, [sp, #48]
    // d = a0 - a1 + p (unreduced, in (0, 2p)) -> x3..x10
    ldp   x11, x12, [x1, #64]
    subs  x3, x3, x11
    sbcs  x4, x4, x12
    ldp   x11, x12, [x1, #80]
    sbcs  x5, x5, x11
    sbcs  x6, x6, x12
    ldp   x11, x12, [x1, #96]
    sbcs  x7, x7, x11
    sbcs  x8, x8, x12
    ldp   x11, x12, [x1, #112]
    sbcs  x9, x9, x11
    sbcs  x10, x10, x12
    mov   x11, #-1
    movz  x12, #0xffff
    movk  x12, #0x43ff, lsl #16
    movk  x12, #0x0009, lsl #32      // p[7]
    adds  x3, x3, x11
    adcs  x4, x4, x11
    adcs  x5, x5, x11
    adcs  x6, x6, x11
    adcs  x7, x7, x11
    adcs  x8, x8, x11
    adcs  x9, x9, x11
    adc   x10, x10, x12

    // c0 = d x s -> [out] (a0's slot; a1 is still intact if c == a)
    // x11..x17,x19,x20 <- z = a x b0
    ldr   x21, [sp]
    MUL64x512  x11,x12,x13,x14,x15,x16,x17,x19,x20, x3,x4,x5,x6,x7,x8,x9,x10, x21, x22
    FPMUL512x512  sp, x3,x4,x5,x6,x7,x8,x9,x10, x11,x12,x13,x14,x15,x16,x17,x19,x20, x21, x22
    // reduce x20,x11..x17 into [0, p)
    mov   x21, #-1
    movz  x22, #0xffff
    movk  x22, #0x43ff, lsl #16
    movk  x22, #0x0009, lsl #32      // p[7]
    subs  x20, x20, x21
    sbcs  x11, x11, x21
    sbcs  x12, x12, x21
    sbcs  x13, x13, x21
    sbcs  x14, x14, x21
    sbcs  x15, x15, x21
    sbcs  x16, x16, x21
    sbcs  x17, x17, x22
    sbc   x21, xzr, xzr              // mask = -borrow
    and   x22, x22, x21
    adds  x20, x20, x21
    adcs  x11, x11, x21
    adcs  x12, x12, x21
    adcs  x13, x13, x21
    adcs  x14, x14, x21
    adcs  x15, x15, x21
    adcs  x16, x16, x21
    adc   x17, x17, x22
    stp   x20, x11, [x0]
    stp   x12, x13, [x0, #16]
    stp   x14, x15, [x0, #32]
    stp   x16, x17, [x0, #48]

    // c1 = a1 x t -> [out+64]
    ldp   x3, x4, [x1, #64]
    ldp   x5, x6, [x1, #80]
    ldp   x7, x8, [x1, #96]
    ldp   x9, x10, [x1, #112]
    add   x1, sp, #64                // x1 is dead after the a1 load: reuse it as the t pointer
    // x20,x11..x17,x19 <- z = a x b0
    ldr   x21, [x1]
    MUL64x512  x20,x11,x12,x13,x14,x15,x16,x17,x19, x3,x4,x5,x6,x7,x8,x9,x10, x21, x22
    FPMUL512x512  x1, x3,x4,x5,x6,x7,x8,x9,x10, x20,x11,x12,x13,x14,x15,x16,x17,x19, x21, x22
    // reduce x19,x20,x11..x16 into [0, p)
    mov   x21, #-1
    movz  x22, #0xffff
    movk  x22, #0x43ff, lsl #16
    movk  x22, #0x0009, lsl #32      // p[7]
    subs  x19, x19, x21
    sbcs  x20, x20, x21
    sbcs  x11, x11, x21
    sbcs  x12, x12, x21
    sbcs  x13, x13, x21
    sbcs  x14, x14, x21
    sbcs  x15, x15, x21
    sbcs  x16, x16, x22
    sbc   x21, xzr, xzr              // mask = -borrow
    and   x22, x22, x21
    adds  x19, x19, x21
    adcs  x20, x20, x21
    adcs  x11, x11, x21
    adcs  x12, x12, x21
    adcs  x13, x13, x21
    adcs  x14, x14, x21
    adcs  x15, x15, x21
    adc   x16, x16, x22
    stp   x19, x20, [x0, #64]
    stp   x11, x12, [x0, #80]
    stp   x13, x14, [x0, #96]
    stp   x15, x16, [x0, #112]
    ldp   x21, x22, [sp, #144]
    ldp   x19, x20, [sp, #128]
    add   sp, sp, #160
    ret
